import{_ as s,C as n,o as c,c as i,a5 as l,E as o,j as e,a as r}from"./chunks/framework.DuVjalqf.js";const g="/rb_cobot_docs_muscat/images/program/if-form.avif",E=JSON.parse('{"title":"조건문 (If)","description":"","frontmatter":{"title":"조건문 (If)","outline":[2,3]},"headers":[],"relativePath":"manual/program/if.md","filePath":"manual/program/if.md","lastUpdated":1792552919000}'),f={name:"manual/program/if.md"};function p(h,t,u,m,b,_){const d=n("DemoFrame"),a=n("ScenarioSteps");return c(),i("div",null,[t[0]||(t[0]=l('<h1 id="조건문-if" tabindex="-1">조건문 (If) <a class="header-anchor" href="#조건문-if" aria-label="Permalink to &quot;조건문 (If)&quot;">​</a></h1><p><strong>조건문</strong>은 조건이 참인지 거짓인지에 따라 실행할 명령을 나누는 명령입니다. 예를 들어 &quot;변수 count가 0이면 A 동작을, 아니면 B 동작을 실행&quot;하는 프로그램을 만들 때 사용합니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>조건문 (If)을 추가하고 조건 입력하기</li><li>조건문 (Else If)·조건문 (Else) 분기 더하기</li><li>각 분기의 실행 결과 이해하기</li></ul><div class="tip custom-block"><p class="custom-block-title">준비</p><p>프로그램이 하나 열려 있어야 합니다. 프로그램이 없으면 <a href="/rb_cobot_docs_muscat/manual/program-create">새 프로그램 만들기</a>를 먼저 따라 합니다.</p></div><h2 id="조건문의-구성" tabindex="-1">조건문의 구성 <a class="header-anchor" href="#조건문의-구성" aria-label="Permalink to &quot;조건문의 구성&quot;">​</a></h2><p>조건문은 하나 이상의 <strong>분기</strong>로 이루어집니다. 분기는 트리에서 같은 높이에 나란히 놓이며, 각 분기에는 조건이 참일 때 실행할 명령을 넣는 <strong>빈 영역</strong>이 함께 생깁니다.</p><table tabindex="0"><thead><tr><th>분기</th><th>트리 이름</th><th>조건</th><th>개수</th></tr></thead><tbody><tr><td><strong>If</strong></td><td>조건문 (If)</td><td>필요합니다.</td><td>처음 한 개</td></tr><tr><td><strong>Else If</strong></td><td>조건문 (Else if)</td><td>필요합니다.</td><td>여러 개</td></tr><tr><td><strong>Else</strong></td><td>조건문 (Else)</td><td>없습니다. 앞의 조건이 모두 거짓일 때 실행합니다.</td><td>한 개만</td></tr></tbody></table><p>프로그램을 실행하면 위에서부터 조건을 차례로 확인해 <strong>처음으로 참인 분기 하나만</strong> 실행하고 나머지 분기는 건너뜁니다. 모든 조건이 거짓이면 Else 분기가 있을 때 그 분기를 실행합니다.</p><h2 id="설정-화면" tabindex="-1">설정 화면 <a class="header-anchor" href="#설정-화면" aria-label="Permalink to &quot;설정 화면&quot;">​</a></h2><p>조건문 (If)을 추가한 뒤 트리의 조건문 (If)을 누르면 오른쪽에 설정 화면이 열립니다. 조건을 입력하기 전의 화면입니다(① 칸에는 예로 <code>count == 0</code>을 입력해 두었습니다).</p><p><img src="'+g+'" alt="조건문 (If) 설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>조건</strong></td><td>분기를 실행할 조건식을 입력합니다. 앞에서 선언한 변수를 쓸 수 있고 <code>count == 0</code>, <code>count % 2 == 0</code>처럼 참·거짓이 나오는 식을 적습니다. 비워 두면 저장할 수 없습니다. 입력칸을 누르면 화면 키보드가 나타납니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>조건문 (Else If) 추가</strong></td><td>앞의 조건이 거짓일 때 확인할 다른 조건 분기를 더합니다. 여러 번 추가할 수 있습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>조건문 (Else) 추가</strong></td><td>앞의 조건이 모두 거짓일 때 실행할 분기를 더합니다. 이미 Else가 있으면 눌리지 않습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>저장</strong></td><td>입력한 조건을 적용하고 설정 화면을 닫습니다. 트리의 조건문 옆에 조건이 표시됩니다.</td></tr></tbody></table></div><p>② ③ 영역은 <strong>조건문 (If)</strong> 설정 화면에만 있습니다. Else If 분기의 설정 화면에는 조건 입력칸만 있고, Else 분기에는 조건이 없어 입력칸이 나타나지 않습니다.</p><div class="warning custom-block"><p class="custom-block-title">추가하기 전에 저장하세요</p><p>② ③으로 분기를 더하면 설정 화면이 새 분기로 바뀝니다. 조건문 (If)에 입력한 조건은 <strong>저장해야</strong> 트리에 남으므로, 분기를 더하기 전에 ⑤ 저장을 먼저 누릅니다.</p></div><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>예제 프로그램은 변수 <code>count</code>를 2로 두고, 조건문의 세 분기(If → Else If → Else)가 <code>result</code>를 각각 1·2·3으로 만든 뒤 <a href="/rb_cobot_docs_muscat/manual/program/repeat#디버그로-값-확인하기">디버그</a> 명령으로 <code>count</code>와 <code>result</code>를 창에 보여 줍니다. 실습은 세 가지이며 어느 쪽부터 해도 되고, 앞의 실습을 하지 않아도 시작할 수 있습니다. 실습을 다시 시작하면 바꾼 값은 처음 상태로 돌아갑니다.</p><h3 id="조건-설정하기" tabindex="-1">조건 설정하기 <a class="header-anchor" href="#조건-설정하기" aria-label="Permalink to &quot;조건 설정하기&quot;">​</a></h3><p>If와 Else If에 조건을 입력하고 저장하는 과정입니다. 시작할 때 두 조건은 비어 있습니다.</p><ol><li>If의 설정 화면을 열어 조건에 <code>count == 0</code>을 입력하고 저장합니다. 입력한 값이 안내와 같아야 다음으로 넘어갈 수 있으며, 공백은 다르게 입력해도 같은 값으로 봅니다. 건너뛰면 자동으로 입력됩니다.</li><li>Else If에도 조건 <code>count &gt; 0</code>을 입력하고 저장합니다.</li></ol>',20)),o(d,{id:"program-if-condition"}),t[1]||(t[1]=e("h4",{id:"사용-방법",tabindex:"-1"},[r("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),o(a,{id:"program-if-condition"}),t[2]||(t[2]=l('<h3 id="분기-실행-확인하기" tabindex="-1">분기 실행 확인하기 <a class="header-anchor" href="#분기-실행-확인하기" aria-label="Permalink to &quot;분기 실행 확인하기&quot;">​</a></h3><p>조건이 이미 입력된 조건문(If: <code>count == 0</code>, Else If: <code>count &gt; 0</code>)을 실행해 어느 분기가 실행되는지 확인하는 과정입니다.</p><ol><li>재생(▶)을 누르면 프로그램이 실행됩니다.</li><li>조건문은 위에서부터 차례로 조건을 확인합니다. <code>count == 0</code>은 거짓이라 건너뛰고 <code>count &gt; 0</code>이 참이라 Else If가 실행되어, 디버그 창에 <code>count: 2.0</code>, <code>result: 2.0</code>이 표시됩니다. Else는 실행되지 않습니다.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">확인 순서</th><th>조건</th><th>결과(<code>count</code>가 2일 때)</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td>If: <code>count == 0</code></td><td>거짓이라 건너뜁니다.</td></tr><tr><td style="text-align:center;">2</td><td>Else If: <code>count &gt; 0</code></td><td><strong>참이라 이 분기를 실행</strong>해 <code>result = 2</code>가 됩니다.</td></tr><tr><td style="text-align:center;">3</td><td>Else</td><td>앞에서 참인 분기가 있었으므로 실행하지 않습니다.</td></tr></tbody></table>',4)),o(d,{id:"program-if-branch"}),t[3]||(t[3]=e("h4",{id:"사용-방법-1",tabindex:"-1"},[r("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),o(a,{id:"program-if-branch"}),t[4]||(t[4]=l('<h3 id="조건을-바꿔-비교하기" tabindex="-1">조건을 바꿔 비교하기 <a class="header-anchor" href="#조건을-바꿔-비교하기" aria-label="Permalink to &quot;조건을 바꿔 비교하기&quot;">​</a></h3><p>If 조건을 바꿔 실행하고 결과를 앞의 실행과 비교하는 과정입니다. 시작할 때 If는 <code>count == 0</code>, Else If는 <code>count &gt; 0</code>입니다.</p><ol><li>If의 설정 화면을 열어 조건을 <code>count == 2</code>로 바꾸고 저장합니다.</li><li>재생(▶)을 누르고 <strong>프로그램 변경 확인</strong> 창에서 <strong>저장</strong>을 누르면 프로그램이 실행됩니다.</li><li><code>count</code>가 2라 If와 Else If가 <strong>모두 참</strong>이지만 <strong>처음으로 참인 분기 하나만</strong> 실행하므로 <code>result: 1.0</code>이 표시됩니다.</li></ol>',3)),o(d,{id:"program-if-compare"}),t[5]||(t[5]=e("h4",{id:"사용-방법-2",tabindex:"-1"},[r("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법-2","aria-label":'Permalink to "사용 방법"'},"​")],-1)),o(a,{id:"program-if-compare"}),t[6]||(t[6]=e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"분기 안에 명령 넣기"),e("p",null,[r("각 분기 아래의 "),e("strong",null,"빈 영역"),r("을 누르고 편집 아이콘으로 명령어 목록을 열어 원하는 명령을 추가하면 그 분기가 선택됐을 때 실행됩니다.")])],-1))])}const x=s(f,[["render",p]]);export{E as __pageData,x as default};
